// Текст закона для сайта (подключается при открытии раздела)
(window.LAW_DATA = window.LAW_DATA || {})["uk"] = {"items":[{"h":"Общая часть"},{"h":"Раздел I. Уголовный закон"},{"h":"Глава 1. Задачи и принципы уголовного кодекса Российской Федерации"},{"n":"Статья 1","title":"Уголовное законодательство Российской Федерации","sub":[{"n":"1","text":"Уголовное законодательство Российской Федерации состоит из настоящего Кодекса. Новые законы, предусматривающие уголовную ответственность, подлежат включению в настоящий Кодекс."},{"n":"2","text":"Настоящий Кодекс основывается на Конституции Российской Федерации и общепризнанных принципах и нормах международного права."}]},{"n":"Статья 2","title":"Задачи Уголовного кодекса Российской Федерации","sub":[{"n":"1","text":"Задачами настоящего Кодекса являются: охрана прав и свобод человека и гражданина, собственности, общественного порядка и общественной безопасности, окружающей среды, конституционного строя Российской Федерации от преступных посягательств, обеспечение мира и безопасности человечества, а также предупреждение преступлений."},{"n":"2","text":"Для осуществления этих задач настоящий Кодекс устанавливает основание и принципы уголовной ответственности, определяет, какие опасные для личности, общества или государства деяния признаются преступлениями, и устанавливает виды наказаний и иные меры уголовно-правового характера за совершение преступлений."}]},{"n":"Статья 3","title":"Принцип законности","sub":[{"n":"1","text":"Преступность деяния, а также его наказуемость и иные уголовно-правовые последствия определяются только настоящим Кодексом."},{"n":"2","text":"Применение уголовного закона по аналогии не допускается."}]},{"n":"Статья 4","title":"Принцип равенства граждан перед законом","text":"Лица, совершившие преступления, равны перед законом и подлежат уголовной ответственности независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств."},{"n":"Статья 5","title":"Принцип вины","sub":[{"n":"1","text":"Лицо подлежит уголовной ответственности только за те общественно опасные действия (бездействие) и наступившие общественно опасные последствия, в отношении которых установлена его вина."},{"n":"2","text":"Объективное вменение, то есть уголовная ответственность за невиновное причинение вреда, не допускается."}]},{"n":"Статья 6","title":"Принцип справедливости","sub":[{"n":"1","text":"Наказание и иные меры уголовно-правового характера, применяемые к лицу, совершившему преступление, должны быть справедливыми, то есть соответствовать характеру и степени общественной опасности преступления, обстоятельствам его совершения и личности виновного."},{"n":"2","text":"Никто не может нести уголовную ответственность дважды за одно и то же преступление."}]},{"n":"Статья 7","title":"Принцип гуманизма","sub":[{"n":"1","text":"Уголовное законодательство Российской Федерации обеспечивает безопасность человека."},{"n":"2","text":"Наказание и иные меры уголовно-правового характера, применяемые к лицу, совершившему преступление, не могут иметь своей целью причинение физических страданий или унижение человеческого достоинства."}]},{"n":"Статья 8","title":"Основание уголовной ответственности","text":"Основанием уголовной ответственности является совершение деяния, содержащего все признаки состава преступления, предусмотренного настоящим Кодексом."},{"h":"Глава 2. Действие уголовного закона во времени и в пространстве"},{"n":"Статья 9","title":"Действие уголовного закона во времени","sub":[{"n":"1","text":"Преступность и наказуемость деяния определяются уголовным законом, действовавшим во время совершения этого деяния."},{"n":"2","text":"Временем совершения преступления признается время совершения общественно опасного действия (бездействия) независимо от времени наступления последствий."}]},{"n":"Статья 10","title":"Обратная сила уголовного закона","sub":[{"n":"1","text":"Уголовный закон, устраняющий преступность деяния, смягчающий наказание или иным образом улучшающий положение лица, совершившего преступление, имеет обратную силу, то есть распространяется на лиц, совершивших соответствующие деяния до вступления такого закона в силу."},{"n":"2","text":"Уголовный закон, устанавливающий преступность деяния, усиливающий наказание или иным образом ухудшающий положение лица, обратной силы не имеет."}]},{"n":"Статья 11","title":"Действие уголовного закона в отношении лиц, совершивших преступление на территории Российской Федерации","sub":[{"n":"1","text":"Уголовный закон действует в отношении всех лиц, совершивших преступление на территории Российской Федерации."},{"n":"2","text":"Преступление признается совершенным на территории Российской Федерации, если оно начато, окончено или прервано на ее территории."}]},{"h":"Глава 3. Понятие преступления и виды преступлений"},{"n":"Статья 12","title":"Понятие преступления","sub":[{"n":"1","text":"Преступлением признается виновно совершенное общественно опасное деяние, запрещенное настоящим Кодексом под угрозой наказания."},{"n":"2","text":"Не является преступлением действие (бездействие), хотя формально и содержащее признаки какого-либо деяния, предусмотренного настоящим Кодексом, но в силу малозначительности не представляющее общественной опасности."}]},{"n":"Статья 13","title":"Категории преступлений","sub":[{"n":"1","text":"В зависимости от характера и степени общественной опасности деяния, предусмотренные настоящим Кодексом, подразделяются на преступления небольшой тяжести, преступления средней тяжести, тяжкие преступления и особо тяжкие преступления."},{"n":"2","text":"Преступлениями небольшой тяжести признаются умышленные и неосторожные деяния, за совершение которых максимальное наказание не превышает двух лет лишения свободы."},{"n":"3","text":"Преступлениями средней тяжести признаются умышленные деяния, за совершение которых максимальное наказание не превышает пяти лет лишения свободы, и неосторожные деяния, за совершение которых максимальное наказание превышает два года лишения свободы."},{"n":"4","text":"Тяжкими преступлениями признаются умышленные деяния, за совершение которых максимальное наказание не превышает десяти лет лишения свободы."},{"n":"5","text":"Особо тяжкими преступлениями признаются умышленные деяния, за совершение которых предусмотрено наказание в виде лишения свободы на срок свыше десяти лет или более строгое наказание."}]},{"n":"Статья 14","title":"Соучастие в преступлении","sub":[{"n":"1","text":"Соучастием в преступлении признается умышленное совместное участие двух или более лиц в совершении умышленного преступления."},{"n":"2","text":"Соучастниками преступления наряду с исполнителем признаются организатор, подстрекатель и пособник."},{"n":"3","text":"Исполнителем признается лицо, непосредственно совершившее преступление либо непосредственно участвовавшее в его совершении совместно с другими лицами."},{"n":"4","text":"Организатором признается лицо, организовавшее совершение преступления или руководившее его исполнением."},{"n":"5","text":"Подстрекателем признается лицо, склонившее другое лицо к совершению преступления путем уговора, подкупа, угрозы или другим способом."},{"n":"6","text":"Пособником признается лицо, содействовавшее совершению преступления советами, указаниями, предоставлением информации, средств или устранением препятствий."}]},{"n":"Статья 15","title":"Возраст, с которого наступает уголовная ответственность","sub":[{"n":"1","text":"Уголовной ответственности подлежит лицо, достигшее ко времени совершения преступления шестнадцатилетнего возраста."},{"n":"2","text":"Лица, достигшие ко времени совершения преступления четырнадцатилетнего возраста, подлежат уголовной ответственности за убийство, умышленное причинение тяжкого вреда здоровью, похищение человека, изнасилование, насильственные действия сексуального характера, кражу, грабеж, разбой, вымогательство, угон, террористический акт, захват заложника, хулиганство при отягчающих обстоятельствах, вандализм, незаконное приобретение и сбыт оружия и наркотических средств."}]},{"h":"Глава 4. Обстоятельства, исключающие преступность деяния"},{"n":"Статья 16","title":"Необходимая оборона","sub":[{"n":"1","text":"Не является преступлением причинение вреда посягающему лицу в состоянии необходимой обороны, то есть при защите личности и прав обороняющегося или других лиц, охраняемых законом интересов общества или государства от общественно опасного посягательства, если это посягательство было сопряжено с насилием, опасным для жизни обороняющегося или другого лица, либо с непосредственной угрозой применения такого насилия."},{"n":"2","text":"Защита от посягательства, не сопряженного с насилием, опасным для жизни обороняющегося или другого лица, является правомерной, если при этом не было допущено превышения пределов необходимой обороны, то есть умышленных действий, явно не соответствующих характеру и опасности посягательства."}]},{"n":"Статья 17","title":"Причинение вреда при задержании лица, совершившего преступление","sub":[{"n":"1","text":"Не является преступлением причинение вреда лицу, совершившему преступление, при его задержании для доставления органам власти и пресечения возможности совершения им новых преступлений, если иными средствами задержать такое лицо не представлялось возможным и при этом не было допущено превышения необходимых для этого мер."},{"n":"2","text":"Превышением мер, необходимых для задержания лица, совершившего преступление, признается их явное несоответствие характеру и степени общественной опасности совершенного задерживаемым лицом преступления и обстоятельствам задержания."}]},{"n":"Статья 18","title":"Крайняя необходимость","sub":[{"n":"1","text":"Не является преступлением причинение вреда охраняемым уголовным законом интересам в состоянии крайней необходимости, то есть для устранения опасности, непосредственно угрожающей личности и правам данного лица или иных лиц, если эта опасность не могла быть устранена иными средствами и при этом не было допущено превышения пределов крайней необходимости."},{"n":"2","text":"Превышением пределов крайней необходимости признается причинение вреда, явно не соответствующего характеру и степени угрожавшей опасности."}]},{"h":"Особенная часть"},{"h":"Раздел VII. Преступления против личности"},{"h":"Глава 5. Преступления против жизни и здоровья"},{"n":"Статья 19","title":"Убийство","sub":[{"n":"1","text":"Убийство, то есть умышленное причинение смерти другому человеку, — наказывается лишением свободы на срок от шести до пятнадцати лет с ограничением свободы на срок до двух лет либо без такового."},{"n":"2","text":"Убийство:а) двух или более лиц;б) лица или его близких в связи с осуществлением данным лицом служебной деятельности или выполнением общественного долга;в) малолетнего или иного лица, заведомо для виновного находящегося в беспомощном состоянии;г) женщины, заведомо для виновного находящейся в состоянии беременности;д) совершенное с особой жестокостью;е) совершенное общеопасным способом;ж) совершенное группой лиц, группой лиц по предварительному сговору или организованной группой;з) из корыстных побуждений или по найму;и) из хулиганских побуждений;к) с целью скрыть другое преступление или облегчить его совершение;л) по мотивам политической, идеологической, расовой, национальной или религиозной ненависти либо вражды, — наказывается лишением свободы на срок от восьми до двадцати лет с ограничением свободы на срок от одного года до двух лет, либо пожизненным лишением свободы."}]},{"n":"Статья 20","title":"Убийство матерью новорожденного ребенка","text":"Убийство матерью новорожденного ребенка во время или сразу же после родов, а равно убийство матерью новорожденного ребенка в условиях психотравмирующей ситуации или в состоянии психического расстройства, не исключающего вменяемости, — наказывается ограничением свободы на срок от двух до четырех лет либо лишением свободы на тот же срок."},{"n":"Статья 21","title":"Убийство, совершенное в состоянии аффекта","text":"Убийство, совершенное в состоянии внезапно возникшего сильного душевного волнения (аффекта), вызванного насилием, издевательством или тяжким оскорблением со стороны потерпевшего, — наказывается ограничением свободы на срок до трех лет либо лишением свободы на тот же срок."},{"n":"Статья 22","title":"Причинение смерти по неосторожности","sub":[{"n":"1","text":"Причинение смерти по неосторожности — наказывается ограничением свободы на срок до двух лет либо лишением свободы на тот же срок."},{"n":"2","text":"Причинение смерти по неосторожности вследствие ненадлежащего исполнения лицом своих профессиональных обязанностей — наказывается ограничением свободы на срок до трех лет либо лишением свободы на тот же срок с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."}]},{"n":"Статья 23","title":"Умышленное причинение тяжкого вреда здоровью","sub":[{"n":"1","text":"Умышленное причинение тяжкого вреда здоровью, опасного для жизни человека, или повлекшего за собой потерю зрения, речи, слуха либо какого-либо органа, — наказывается лишением свободы на срок до восьми лет."},{"n":"2","text":"Те же деяния, совершенные:а) в отношении лица или его близких в связи с осуществлением данным лицом служебной деятельности;б) с особой жестокостью;в) общеопасным способом;г) по найму;д) из хулиганских побуждений;е) с применением оружия или предметов, используемых в качестве оружия;ж) группой лиц, группой лиц по предварительному сговору или организованной группой, — наказываются лишением свободы на срок до двенадцати лет."},{"n":"3","text":"Деяния, предусмотренные частями первой или второй настоящей статьи, повлекшие по неосторожности смерть потерпевшего, — наказываются лишением свободы на срок до пятнадцати лет."}]},{"n":"Статья 24","title":"Умышленное причинение средней тяжести вреда здоровью","sub":[{"n":"1","text":"Умышленное причинение средней тяжести вреда здоровью, не опасного для жизни человека и не повлекшего последствий, указанных в статье 23 настоящего Кодекса, — наказывается ограничением свободы на срок до трех лет либо лишением свободы на тот же срок."},{"n":"2","text":"То же деяние, совершенное с применением оружия или предметов, используемых в качестве оружия, из хулиганских побуждений, группой лиц, — наказывается лишением свободы на срок до пяти лет."}]},{"n":"Статья 25","title":"Умышленное причинение легкого вреда здоровью","text":"Умышленное причинение легкого вреда здоровью, вызвавшего кратковременное расстройство здоровья или незначительную стойкую утрату общей трудоспособности, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"Статья 26","title":"Побои","sub":[{"n":"1","text":"Нанесение побоев или совершение иных насильственных действий, причинивших физическую боль, но не повлекших последствий, указанных в статье 25 настоящего Кодекса, — наказывается штрафом, либо обязательными работами, либо арестом."},{"n":"2","text":"Те же деяния, совершенные из хулиганских побуждений, — наказываются обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до двух лет."}]},{"n":"Статья 27","title":"Истязание","sub":[{"n":"1","text":"Причинение физических или психических страданий путем систематического нанесения побоев либо иными насильственными способами, если это не повлекло последствий, указанных в статьях 23 и 24 настоящего Кодекса, — наказывается ограничением свободы на срок до трех лет либо лишением свободы на тот же срок."},{"n":"2","text":"То же деяние, совершенное с применением пытки, группой лиц, — наказывается лишением свободы на срок от трех до семи лет."}]},{"n":"Статья 28","title":"Угроза убийством или причинением тяжкого вреда здоровью","text":"Угроза убийством или причинением тяжкого вреда здоровью, если имелись основания опасаться осуществления этой угрозы, — наказывается ограничением свободы на срок до двух лет либо лишением свободы на тот же срок."},{"n":"Статья 29","title":"Оставление в опасности","text":"Заведомое оставление без помощи лица, находящегося в опасном для жизни или здоровья состоянии и лишенного возможности принять меры к самосохранению, в случаях, если виновный имел возможность оказать помощь этому лицу и был обязан иметь о нем заботу либо сам поставил его в опасное для жизни или здоровья состояние, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до одного года."},{"n":"Статья 30","title":"Незаконная медицинская и фармацевтическая деятельность","sub":[{"n":"1","text":"Занятие частной медицинской практикой или частной фармацевтической деятельностью лицом, не имеющим лицензии на избранный вид деятельности, если это повлекло по неосторожности причинение вреда здоровью человека, — наказывается штрафом, либо ограничением свободы на срок до трех лет, либо лишением свободы на тот же срок."},{"n":"2","text":"То же деяние, повлекшее по неосторожности смерть человека, — наказывается лишением свободы на срок до пяти лет."}]},{"n":"Статья 31","title":"Оказание услуг, не отвечающих требованиям безопасности","sub":[{"n":"1","text":"Оказание услуг, не отвечающих требованиям безопасности жизни или здоровья потребителей, — наказывается штрафом, либо обязательными работами, либо ограничением свободы на срок до двух лет."},{"n":"2","text":"Те же деяния, повлекшие по неосторожности причинение тяжкого вреда здоровью либо смерть человека, — наказываются лишением свободы на срок до шести лет."}]},{"h":"Глава 6. Преступления против свободы, чести и достоинства личности"},{"n":"Статья 32","title":"Похищение человека","sub":[{"n":"1","text":"Похищение человека — наказывается принудительными работами на срок до пяти лет либо лишением свободы на тот же срок."},{"n":"2","text":"То же деяние, совершенное:а) группой лиц по предварительному сговору;б) с применением насилия, опасного для жизни или здоровья, либо с угрозой применения такого насилия;в) с применением оружия или предметов, используемых в качестве оружия;г) в отношении заведомо несовершеннолетнего;д) в отношении женщины, заведомо для виновного находящейся в состоянии беременности;е) в отношении двух или более лиц;ж) из корыстных побуждений, — наказывается лишением свободы на срок от пяти до двенадцати лет с ограничением свободы на срок до двух лет либо без такового."},{"n":"3","text":"Деяния, предусмотренные частями первой или второй настоящей статьи, если они совершены организованной группой либо повлекли по неосторожности смерть потерпевшего или иные тяжкие последствия, — наказываются лишением свободы на срок от шести до пятнадцати лет с ограничением свободы на срок до двух лет либо без такового."},{"n":"","text":"Примечание. Лицо, добровольно освободившее похищенного, освобождается от уголовной ответственности, если в его действиях не содержится иного состава преступления."}]},{"n":"Статья 33","title":"Незаконное лишение свободы","sub":[{"n":"1","text":"Незаконное лишение человека свободы, не связанное с его похищением, — наказывается ограничением свободы на срок до двух лет либо лишением свободы на тот же срок."},{"n":"2","text":"То же деяние, совершенное с применением насилия, опасного для жизни или здоровья, с применением оружия, из корыстных побуждений, — наказывается лишением свободы на срок до пяти лет."}]},{"n":"Статья 34","title":"Торговля людьми","sub":[{"n":"1","text":"Купля-продажа человека, иные сделки в отношении человека, а равно совершенные в целях его эксплуатации вербовка, перевозка, передача, укрывательство или получение — наказываются лишением свободы на срок до шести лет."},{"n":"2","text":"Те же деяния, совершенные в отношении двух или более лиц, в отношении заведомо несовершеннолетнего, с применением насилия, группой лиц по предварительному сговору, — наказываются лишением свободы на срок от четырех до десяти лет."}]},{"n":"Статья 35","title":"Использование рабского труда","text":"Использование труда человека, в отношении которого осуществляются полномочия, присущие праву собственности, в случае, если лицо по не зависящим от него причинам не может отказаться от работ (услуг), — наказывается лишением свободы на срок до пяти лет."},{"n":"Статья 36","title":"Клевета","sub":[{"n":"1","text":"Клевета, то есть распространение заведомо ложных сведений, порочащих честь и достоинство другого лица или подрывающих его репутацию, — наказывается штрафом либо обязательными работами."},{"n":"2","text":"Клевета, содержащаяся в публичном выступлении, публично демонстрирующемся произведении или средствах массовой информации, — наказывается штрафом, либо обязательными работами, либо исправительными работами."}]},{"n":"Статья 37","title":"Оскорбление","sub":[{"n":"1","text":"Оскорбление, то есть унижение чести и достоинства другого лица, выраженное в неприличной форме, — наказывается штрафом либо обязательными работами."},{"n":"2","text":"Оскорбление, содержащееся в публичном выступлении, публично демонстрирующемся произведении или средствах массовой информации, — наказывается штрафом, либо обязательными работами, либо исправительными работами."}]},{"h":"Глава 7. Преступления против половой неприкосновенности и половой свободы личности"},{"n":"Статья 38","title":"Изнасилование","sub":[{"n":"1","text":"Изнасилование, то есть половое сношение с применением насилия или с угрозой его применения к потерпевшей или к другим лицам либо с использованием беспомощного состояния потерпевшей, — наказывается лишением свободы на срок от трех до шести лет."},{"n":"2","text":"Изнасилование:а) совершенное группой лиц, группой лиц по предварительному сговору или организованной группой;б) соединенное с угрозой убийством или причинением тяжкого вреда здоровью, а также совершенное с особой жестокостью;в) повлекшее заражение потерпевшей венерическим заболеванием, — наказывается лишением свободы на срок от четырех до десяти лет с ограничением свободы на срок до двух лет либо без такового."},{"n":"3","text":"Изнасилование несовершеннолетней, а равно повлекшее по неосторожности причинение тяжкого вреда здоровью потерпевшей, заражение ее ВИЧ-инфекцией или иные тяжкие последствия, — наказывается лишением свободы на срок от восьми до пятнадцати лет."}]},{"n":"Статья 39","title":"Насильственные действия сексуального характера","sub":[{"n":"1","text":"Мужеложство, лесбиянство или иные действия сексуального характера с применением насилия или с угрозой его применения к потерпевшему (потерпевшей) либо с использованием беспомощного состояния потерпевшего (потерпевшей) — наказываются лишением свободы на срок от трех до шести лет."},{"n":"2","text":"Те же деяния, совершенные группой лиц, соединенные с угрозой убийством, повлекшие заражение венерическим заболеванием, — наказываются лишением свободы на срок от четырех до десяти лет."}]},{"n":"Статья 40","title":"Понуждение к действиям сексуального характера","text":"Понуждение лица к половому сношению, мужеложству, лесбиянству или совершению иных действий сексуального характера путем шантажа, угрозы уничтожением, повреждением или изъятием имущества либо с использованием материальной или иной зависимости потерпевшего (потерпевшей) — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до одного года."},{"h":"Глава 8. Преступления против конституционных прав и свобод человека и гражданина"},{"n":"Статья 41","title":"Нарушение неприкосновенности частной жизни","sub":[{"n":"1","text":"Незаконное собирание или распространение сведений о частной жизни лица, составляющих его личную или семейную тайну, без его согласия — наказывается штрафом, либо обязательными работами, либо исправительными работами."},{"n":"2","text":"Те же деяния, совершенные лицом с использованием своего служебного положения, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо арестом."}]},{"n":"Статья 42","title":"Нарушение тайны переписки, телефонных переговоров, почтовых, телеграфных или иных сообщений","sub":[{"n":"1","text":"Нарушение тайны переписки, телефонных переговоров, почтовых, телеграфных или иных сообщений граждан — наказывается штрафом, либо обязательными работами, либо исправительными работами."},{"n":"2","text":"То же деяние, совершенное лицом с использованием своего служебного положения, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."}]},{"n":"Статья 43","title":"Нарушение неприкосновенности жилища","sub":[{"n":"1","text":"Незаконное проникновение в жилище, совершенное против воли проживающего в нем лица, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"2","text":"То же деяние, совершенное с применением насилия или с угрозой его применения, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до двух лет."}]},{"n":"Статья 44","title":"Воспрепятствование проведению собрания, митинга, демонстрации, шествия, пикетирования","text":"Незаконное воспрепятствование проведению собрания, митинга, демонстрации, шествия, пикетирования или участию в них либо принуждение к участию в них, если эти деяния совершены должностным лицом с использованием своего служебного положения, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."},{"n":"Статья 45","title":"Нарушение правил охраны труда","sub":[{"n":"1","text":"Нарушение требований охраны труда, совершенное лицом, на которое возложены обязанности по их соблюдению, если это повлекло по неосторожности причинение тяжкого вреда здоровью человека, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до одного года с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."},{"n":"2","text":"То же деяние, повлекшее по неосторожности смерть человека, — наказывается лишением свободы на срок до четырех лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."}]},{"n":"Статья 46","title":"Нарушение авторских и смежных прав","sub":[{"n":"1","text":"Незаконное использование объектов авторского права или смежных прав, а равно приобретение, хранение, перевозка контрафактных экземпляров произведений или фонограмм в целях сбыта, совершенные в крупном размере, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до двух лет."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору или организованной группой, — наказываются лишением свободы на срок до пяти лет со штрафом."}]},{"h":"Глава 9. Преступления против семьи и несовершеннолетних"},{"n":"Статья 47","title":"Вовлечение несовершеннолетнего в совершение преступления","sub":[{"n":"1","text":"Вовлечение несовершеннолетнего в совершение преступления путем обещаний, обмана, угроз или иным способом, совершенное лицом, достигшим восемнадцатилетнего возраста, — наказывается лишением свободы на срок до пяти лет."},{"n":"2","text":"То же деяние, совершенное в отношении двух или более несовершеннолетних, группой лиц по предварительному сговору, с применением насилия, — наказывается лишением свободы на срок от трех до семи лет."}]},{"n":"Статья 48","title":"Вовлечение несовершеннолетнего в совершение антиобщественных действий","text":"Вовлечение несовершеннолетнего в систематическое употребление спиртных напитков, одурманивающих веществ, в занятие бродяжничеством или попрошайничеством — наказывается обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до четырех лет."},{"n":"Статья 49","title":"Неисполнение обязанностей по воспитанию несовершеннолетнего","text":"Неисполнение или ненадлежащее исполнение обязанностей по воспитанию несовершеннолетнего родителем или иным лицом, на которое возложены эти обязанности, а равно педагогическим работником, если это деяние соединено с жестоким обращением с несовершеннолетним, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до пяти лет."},{"n":"Статья 50","title":"Злостное уклонение от уплаты средств на содержание детей","text":"Злостное уклонение родителя от уплаты по решению суда средств на содержание несовершеннолетних детей, а равно нетрудоспособных детей, достигших восемнадцатилетнего возраста, — наказывается исправительными работами, либо арестом, либо лишением свободы на срок до одного года."},{"n":"Статья 51","title":"Незаконное усыновление (удочерение)","text":"Незаконные действия по усыновлению (удочерению) детей, передаче их под опеку (попечительство), на воспитание в приемные семьи, совершенные неоднократно или из корыстных побуждений, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"Статья 52","title":"Разглашение тайны усыновления (удочерения)","text":"Разглашение тайны усыновления (удочерения) вопреки воле усыновителя, совершенное лицом, обязанным хранить факт усыновления как служебную или профессиональную тайну, либо иным лицом из корыстных или иных низменных побуждений, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"h":"Глава 10. Преступления против собственности"},{"n":"Статья 53","title":"Кража","sub":[{"n":"1","text":"Кража, то есть тайное хищение чужого имущества, — наказывается штрафом в размере до восьмидесяти тысяч рублей, либо обязательными работами на срок до трехсот шестидесяти часов, либо исправительными работами на срок до одного года, либо ограничением свободы на срок до двух лет, либо принудительными работами на срок до двух лет, либо арестом, либо лишением свободы на срок до двух лет."},{"n":"2","text":"Кража, совершенная:а) группой лиц по предварительному сговору;б) с незаконным проникновением в помещение либо иное хранилище;в) с причинением значительного ущерба гражданину;г) из одежды, сумки или другой ручной клади, находившихся при потерпевшем, — наказывается штрафом в размере до двухсот тысяч рублей, либо обязательными работами на срок до четырехсот восьмидесяти часов, либо исправительными работами на срок до двух лет, либо принудительными работами на срок до пяти лет с ограничением свободы на срок до одного года или без такового, либо лишением свободы на срок до пяти лет с ограничением свободы на срок до одного года или без такового."},{"n":"3","text":"Кража, совершенная:а) с незаконным проникновением в жилище;б) из нефтепровода, нефтепродуктопровода, газопровода;в) в крупном размере, — наказывается штрафом в размере от ста тысяч до пятисот тысяч рублей, либо принудительными работами на срок до пяти лет с ограничением свободы на срок до полутора лет или без такового, либо лишением свободы на срок до шести лет со штрафом в размере до восьмидесяти тысяч рублей или без такового и с ограничением свободы на срок до полутора лет или без такового."},{"n":"4","text":"Кража, совершенная:а) организованной группой;б) в особо крупном размере, — наказывается лишением свободы на срок до десяти"},{"n":"","text":"лет со штрафом в размере до одного миллиона рублей или без такового и с ограничением свободы на срок до двух лет либо без такового."},{"n":"","text":"Примечание. Значительным ущербом в статьях настоящей главы признается ущерб, определяемый с учетом имущественного положения потерпевшего, но не менее пяти тысяч рублей. Крупным размером признается стоимость имущества, превышающая двести пятьдесят тысяч рублей, особо крупным — один миллион рублей."}]},{"n":"Статья 54","title":"Мошенничество","sub":[{"n":"1","text":"Мошенничество, то есть хищение чужого имущества или приобретение права на чужое имущество путем обмана или злоупотребления доверием, — наказывается штрафом в размере до ста двадцати тысяч рублей, либо обязательными работами на срок до трехсот шестидесяти часов, либо исправительными работами на срок до одного года, либо ограничением свободы на срок до двух лет, либо принудительными работами на срок до двух лет, либо арестом, либо лишением свободы на срок до двух лет."},{"n":"2","text":"Мошенничество, совершенное:а) группой лиц по предварительному сговору;б) с причинением значительного ущерба гражданину, — наказывается штрафом в размере до трехсот тысяч рублей, либо обязательными работами на срок до четырехсот восьмидесяти часов, либо исправительными работами на срок до двух лет, либо принудительными работами на срок до пяти лет с ограничением свободы на срок до одного года или без такового, либо лишением свободы на срок до пяти лет с ограничением свободы на срок до одного года или без такового."},{"n":"3","text":"Мошенничество, совершенное:а) лицом с использованием своего служебного положения;б) в крупном размере, — наказывается штрафом в размере от ста тысяч до пятисот тысяч рублей, либо принудительными работами на срок до пяти лет с ограничением свободы на срок до двух лет или без такового, либо лишением свободы на срок до шести лет со штрафом в размере до восьмидесяти тысяч рублей или без такового и с ограничением свободы на срок до полутора лет либо без такового."},{"n":"4","text":"Мошенничество, совершенное организованной группой либо в особо крупном размере, — наказывается лишением свободы на срок до десяти лет со штрафом в размере до одного миллиона рублей или без такового и с ограничением свободы на срок до двух лет либо без такового."}]},{"n":"Статья 55","title":"Присвоение или растрата","sub":[{"n":"1","text":"Присвоение или растрата, то есть хищение чужого имущества, вверенного виновному, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до двух лет."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору, с использованием своего служебного положения, с причинением значительного ущерба гражданину, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до пяти лет со штрафом."}]},{"n":"Статья 56","title":"Грабеж","sub":[{"n":"1","text":"Грабеж, то есть открытое хищение чужого имущества, — наказывается обязательными работами на срок до четырехсот восьмидесяти часов, либо исправительными работами на срок до двух лет, либо ограничением свободы на срок от двух до четырех лет, либо принудительными работами на срок до четырех лет, либо арестом на срок до шести месяцев, либо лишением свободы на срок до четырех лет."},{"n":"2","text":"Грабеж, совершенный:а) группой лиц по предварительному сговору;б) с незаконным проникновением в жилище, помещение либо иное хранилище;в) с применением насилия, не опасного для жизни или здоровья, либо с угрозой применения такого насилия;г) в крупном размере, — наказывается принудительными работами на срок до пяти лет либо лишением свободы на срок до семи лет со штрафом в размере до десяти тысяч рублей или без такового и с ограничением свободы на срок до одного года или без такового."},{"n":"3","text":"Грабеж, совершенный организованной группой либо в особо крупном размере, — наказывается лишением свободы на срок от шести до двенадцати лет со штрафом в размере до одного миллиона рублей или без такового и с ограничением свободы на срок до двух лет либо без такового."}]},{"n":"Статья 57","title":"Разбой","sub":[{"n":"1","text":"Разбой, то есть нападение в целях хищения чужого имущества, совершенное с применением насилия, опасного для жизни или здоровья, либо с угрозой применения такого насилия, — наказывается принудительными работами на срок до пяти лет либо лишением свободы на срок до восьми лет со штрафом в размере до пятисот тысяч рублей или без такового."},{"n":"2","text":"Разбой, совершенный группой лиц по предварительному сговору, а равно с применением оружия или предметов, используемых в качестве оружия, — наказывается лишением свободы на срок до десяти лет со штрафом в размере до одного миллиона рублей или без такового и с ограничением свободы на срок до двух лет либо без такового."},{"n":"3","text":"Разбой, совершенный с незаконным проникновением в жилище, помещение либо иное хранилище или в крупном размере, — наказывается лишением свободы на срок от семи до двенадцати лет со штрафом в размере до одного миллиона рублей или без такового и с ограничением свободы на срок до двух лет либо без такового."},{"n":"4","text":"Разбой, совершенный:а) организованной группой;б) в особо крупном размере;в) с причинением тяжкого вреда здоровью потерпевшего, — наказывается лишением свободы на срок от восьми до пятнадцати лет со штрафом в размере до одного миллиона рублей или без такового и с ограничением свободы на срок до двух лет либо без такового."}]},{"n":"Статья 58","title":"Вымогательство","sub":[{"n":"1","text":"Вымогательство, то есть требование передачи чужого имущества или права на имущество или совершения других действий имущественного характера под угрозой применения насилия либо уничтожения или повреждения чужого имущества, а равно под угрозой распространения сведений, позорящих потерпевшего или его близких, — наказывается ограничением свободы на срок до четырех лет, либо принудительными работами на срок до четырех лет с ограничением свободы на срок до двух лет или без такового, либо арестом на срок до шести месяцев, либо лишением свободы на срок до четырех лет со штрафом в размере до восьмидесяти тысяч рублей или без такового."},{"n":"2","text":"Вымогательство, совершенное:а) группой лиц по предварительному сговору;б) с применением насилия;в) в крупном размере, — наказывается лишением свободы на срок до семи лет со штрафом в размере до пятисот тысяч рублей или без такового и с ограничением свободы на срок до двух лет либо без такового."},{"n":"3","text":"Вымогательство, совершенное:а) организованной группой;б) в целях получения имущества в особо крупном размере;в) с причинением тяжкого вреда здоровью потерпевшего, — наказывается лишением свободы на срок от семи до пятнадцати лет со штрафом в размере до одного миллиона рублей или без такового и с ограничением свободы на срок до двух лет либо без такового."}]},{"n":"Статья 59","title":"Хищение предметов, имеющих особую ценность","text":"Хищение предметов или документов, имеющих особую историческую, научную, художественную или культурную ценность, независимо от способа хищения — наказывается лишением свободы на срок до десяти лет со штрафом."},{"n":"Статья 60","title":"Умышленное уничтожение или повреждение имущества","sub":[{"n":"1","text":"Умышленное уничтожение или повреждение чужого имущества, если эти деяния повлекли причинение значительного ущерба, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до двух лет."},{"n":"2","text":"Те же деяния, совершенные из хулиганских побуждений, путем поджога, взрыва или иным общеопасным способом, — наказываются лишением свободы на срок до пяти лет."}]},{"n":"Статья 61","title":"Уничтожение или повреждение имущества по неосторожности","text":"Уничтожение или повреждение чужого имущества в крупном размере, совершенные путем неосторожного обращения с огнем или иными источниками повышенной опасности, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо ограничением свободы на срок до двух лет, либо лишением свободы на тот же срок."},{"n":"Статья 62","title":"Угон","sub":[{"n":"1","text":"Неправомерное завладение автомобилем или иным транспортным средством без цели хищения (угон) — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до пяти лет."},{"n":"2","text":"То же деяние, совершенное группой лиц по предварительному сговору, с применением насилия, не опасного для жизни или здоровья, — наказывается лишением свободы на срок до семи лет со штрафом."}]},{"n":"Статья 63","title":"Приобретение или сбыт имущества, заведомо добытого преступным путем","text":"Заранее не обещанные приобретение или сбыт имущества, заведомо добытого преступным путем, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до двух лет."},{"n":"Статья 64","title":"Самовольное занятие земельного участка","text":"Самовольное занятие земельного участка, если это деяние причинило значительный ущерб гражданину или организации, — наказывается штрафом, либо обязательными работами, либо исправительными работами."},{"h":"Глава 11. Преступления в сфере экономической деятельности"},{"n":"Статья 65","title":"Незаконное предпринимательство","sub":[{"n":"1","text":"Осуществление предпринимательской деятельности без регистрации или без лицензии, если это деяние причинило крупный ущерб гражданам, организациям или государству либо сопряжено с извлечением дохода в крупном размере, — наказывается штрафом, либо обязательными работами, либо арестом на срок до шести месяцев."},{"n":"2","text":"То же деяние, совершенное организованной группой либо сопряженное с извлечением дохода в особо крупном размере, — наказывается штрафом, либо лишением свободы на срок до пяти лет со штрафом."}]},{"n":"Статья 66","title":"Незаконная банковская деятельность","text":"Осуществление банковской деятельности без регистрации или без лицензии, если это деяние причинило крупный ущерб гражданам, организациям или государству либо сопряжено с извлечением дохода в крупном размере, — наказывается штрафом, либо обязательными работами, либо лишением свободы на срок до четырех лет со штрафом."},{"n":"Статья 67","title":"Легализация (отмывание) денежных средств или иного имущества, приобретенных преступным путем","sub":[{"n":"1","text":"Совершение финансовых операций и других сделок с денежными средствами или иным имуществом, приобретенными заведомо преступным путем, в целях придания правомерного вида владению, пользованию и распоряжению указанными средствами, — наказывается штрафом, либо обязательными работами, либо лишением свободы на срок до четырех лет со штрафом."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору, лицом с использованием своего служебного положения, в крупном размере, — наказываются лишением свободы на срок до семи лет со штрафом."}]},{"n":"Статья 68","title":"Незаконное получение кредита","text":"Получение индивидуальным предпринимателем или руководителем организации кредита либо льготных условий кредитования путем представления банку или иному кредитору заведомо ложных сведений о хозяйственном положении либо финансовом состоянии, если это деяние причинило крупный ущерб, — наказывается штрафом, либо обязательными работами, либо арестом, либо лишением свободы на срок до пяти лет со штрафом."},{"n":"Статья 69","title":"Злостное уклонение от погашения кредиторской задолженности","text":"Злостное уклонение руководителя организации или гражданина от погашения кредиторской задолженности в крупном размере или от оплаты ценных бумаг после вступления в законную силу соответствующего судебного акта — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до двух лет."},{"n":"Статья 70","title":"Ограничение конкуренции","text":"Ограничение конкуренции путем заключения между хозяйствующими субъектами-конкурентами соглашения, если это деяние причинило крупный ущерб гражданам, организациям или государству либо сопряжено с извлечением дохода в крупном размере, — наказывается штрафом, либо лишением свободы на срок до трех лет со штрафом."},{"n":"Статья 71","title":"Незаконное использование товарного знака","text":"Незаконное использование чужого товарного знака, знака обслуживания, наименования места происхождения товара или сходных с ними обозначений для однородных товаров, если это деяние совершено неоднократно или причинило крупный ущерб, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до двух лет со штрафом."},{"n":"Статья 72","title":"Заведомо ложная реклама","text":"Использование в рекламе заведомо ложной информации относительно товаров, работ или услуг, а также их изготовителей (исполнителей, продавцов), совершенное из корыстной заинтересованности и причинившее значительный ущерб, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до двух лет со штрафом."},{"n":"Статья 73","title":"Уклонение от уплаты налогов и сборов","sub":[{"n":"1","text":"Уклонение от уплаты налогов и сборов путем непредставления налоговой декларации или иных документов, представление которых обязательно, либо путем включения в налоговую декларацию заведомо ложных сведений, совершенное в крупном размере, — наказывается штрафом, либо обязательными работами, либо арестом, либо лишением свободы на срок до одного года."},{"n":"2","text":"То же деяние, совершенное группой лиц по предварительному сговору, в особо крупном размере, — наказывается штрафом, либо лишением свободы на срок до трех лет со штрафом."}]},{"n":"Статья 74","title":"Сокрытие денежных средств либо имущества организации, за счет которых должно производиться взыскание налогов","text":"Сокрытие денежных средств либо имущества организации, за счет которых в порядке, предусмотренном законодательством, должно быть произведено взыскание недоимки по налогам и сборам, совершенное собственником или руководителем организации в крупном размере, — наказывается штрафом, либо лишением свободы на срок до пяти лет со штрафом."},{"n":"Статья 75","title":"Уклонение от уплаты таможенных платежей","text":"Уклонение от уплаты таможенных платежей, взимаемых с организации или физического лица, совершенное в крупном размере, — наказывается штрафом, либо обязательными работами, либо лишением свободы на срок до двух лет."},{"n":"Статья 76","title":"Фальшивомонетничество","sub":[{"n":"1","text":"Изготовление, хранение, перевозка в целях сбыта или сбыт поддельных банковских билетов Центрального банка Российской Федерации, металлической монеты, государственных ценных бумаг или других ценных бумаг в валюте Российской Федерации либо иностранной валюты или ценных бумаг в иностранной валюте — наказываются лишением свободы на срок до восьми лет со штрафом."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору или организованной группой, в крупном размере, — наказываются лишением свободы на срок до пятнадцати лет со штрафом."}]},{"n":"Статья 77","title":"Незаконный оборот драгоценных металлов и камней","sub":[{"n":"1","text":"Совершение сделок, связанных с драгоценными металлами, природными драгоценными камнями либо жемчугом, в нарушение правил, установленных законодательством Российской Федерации, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору или организованной группой, в крупном размере, — наказываются лишением свободы на срок до семи лет со штрафом."}]},{"n":"Статья 78","title":"Обман потребителей","text":"Обмеривание, обвешивание, обсчет, введение в заблуждение относительно потребительских свойств или качества товара (услуги) или иной обман потребителей в организациях, осуществляющих реализацию товаров или оказывающих услуги, если эти деяния совершены в значительном размере, — наказываются штрафом, либо обязательными работами, либо исправительными работами."},{"n":"Статья 79","title":"Преднамеренное банкротство","text":"Преднамеренное создание или увеличение неплатежеспособности, совершенное руководителем или собственником коммерческой организации в личных интересах или интересах иных лиц, причинившее крупный ущерб, — наказывается штрафом, либо обязательными работами, либо лишением свободы на срок до шести лет со штрафом."},{"h":"Глава 12. Преступления против интересов службы в коммерческих организациях"},{"n":"Статья 80","title":"Злоупотребление полномочиями","sub":[{"n":"1","text":"Использование лицом, выполняющим управленческие функции в коммерческой или иной организации, своих полномочий вопреки законным интересам этой организации в целях извлечения выгод и преимуществ для себя или других лиц либо нанесения вреда другим лицам, если это деяние повлекло причинение существенного вреда правам и законным интересам граждан или организаций, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до четырех лет со штрафом."},{"n":"2","text":"То же деяние, повлекшее тяжкие последствия, — наказывается штрафом, либо лишением свободы на срок до десяти лет со штрафом."}]},{"n":"Статья 81","title":"Коммерческий подкуп","sub":[{"n":"1","text":"Незаконная передача лицу, выполняющему управленческие функции в коммерческой или иной организации, денег, ценных бумаг, иного имущества за совершение действий (бездействие) в интересах дающего — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет со штрафом."},{"n":"2","text":"Незаконное получение лицом, выполняющим управленческие функции в коммерческой или иной организации, денег, ценных бумаг, иного имущества за совершение действий (бездействие) в интересах дающего — наказывается штрафом, либо лишением свободы на срок до пяти лет со штрафом."}]},{"n":"Статья 82","title":"Превышение полномочий частными охранными и детективными службами","text":"Превышение руководителем или служащим частной охранной или детективной службы полномочий, предоставленных им в соответствии с лицензией, вопреки задачам своей деятельности, если это деяние совершено с применением насилия или с угрозой его применения, — наказывается ограничением свободы на срок до трех лет либо лишением свободы на тот же срок с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."},{"h":"Раздел VIII. Преступления в сфере экономики"},{"h":"Глава 13. Преступления против общественной безопасности"},{"n":"Статья 83","title":"Террористический акт","sub":[{"n":"1","text":"Совершение взрыва, поджога или иных действий, устрашающих население и создающих опасность гибели человека, причинения значительного имущественного ущерба, в целях дестабилизации деятельности органов власти или воздействия на принятие ими решений, а также угроза совершения указанных действий в тех же целях — наказываются лишением свободы на срок от восьми до пятнадцати лет со штрафом."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору или организованной группой, повлекшие по неосторожности смерть человека, — наказываются лишением свободы на срок от десяти до двадцати лет со штрафом."},{"n":"3","text":"Деяния, предусмотренные частями первой или второй настоящей статьи, повлекшие умышленное причинение смерти человеку, — наказываются лишением свободы на срок от пятнадцати до двадцати лет или пожизненным лишением свободы."}]},{"n":"Статья 84","title":"Захват заложника","sub":[{"n":"1","text":"Захват или удержание лица в качестве заложника, совершенные в целях понуждения государства, организации или гражданина совершить какое-либо действие или воздержаться от совершения какого-либо действия как условия освобождения заложника, — наказываются лишением свободы на срок от пяти до десяти лет."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору, с применением насилия, опасного для жизни или здоровья, с применением оружия, в отношении заведомо несовершеннолетнего, из корыстных побуждений, — наказываются лишением свободы на срок от восьми до пятнадцати лет со штрафом."},{"n":"3","text":"Деяния, предусмотренные частями первой или второй настоящей статьи, если они совершены организованной группой либо повлекли по неосторожности смерть человека или иные тяжкие последствия, — наказываются лишением свободы на срок от десяти до двадцати лет со штрафом."}]},{"n":"Статья 85","title":"Заведомо ложное сообщение об акте терроризма","text":"Заведомо ложное сообщение о готовящихся взрыве, поджоге или иных действиях, создающих опасность гибели людей, причинения значительного имущественного ущерба либо наступления иных общественно опасных последствий, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до трех лет."},{"n":"Статья 86","title":"Организация незаконного вооруженного формирования","sub":[{"n":"1","text":"Создание вооруженного формирования (объединения, отряда, дружины или иной группы), не предусмотренного законодательством, а равно руководство таким формированием или его финансирование — наказываются лишением свободы на срок от восьми до пятнадцати лет."},{"n":"2","text":"Участие в вооруженном формировании, не предусмотренном законодательством, — наказывается лишением свободы на срок от пяти до десяти лет."}]},{"n":"Статья 87","title":"Бандитизм","sub":[{"n":"1","text":"Создание устойчивой вооруженной группы (банды) в целях нападения на граждан или организации, а равно руководство такой группой (бандой) — наказываются лишением свободы на срок от десяти до пятнадцати лет со штрафом."},{"n":"2","text":"Участие в устойчивой вооруженной группе (банде) или в совершаемых ею нападениях — наказывается лишением свободы на срок от восьми до пятнадцати лет со штрафом."}]},{"n":"Статья 88","title":"Организация преступного сообщества (преступной организации)","sub":[{"n":"1","text":"Создание преступного сообщества (преступной организации) для совершения тяжких или особо тяжких преступлений, а равно руководство таким сообществом или входящими в него структурными подразделениями — наказываются лишением свободы на срок от двенадцати до двадцати лет со штрафом."},{"n":"2","text":"Участие в преступном сообществе (преступной организации) — наказывается лишением свободы на срок от семи до двенадцати лет со штрафом."}]},{"n":"Статья 89","title":"Массовые беспорядки","sub":[{"n":"1","text":"Организация массовых беспорядков, сопровождавшихся насилием, погромами, поджогами, уничтожением или повреждением имущества, применением оружия или предметов, используемых в качестве оружия, — наказывается лишением свободы на срок от восьми до пятнадцати лет."},{"n":"2","text":"Участие в массовых беспорядках, предусмотренных частью первой настоящей статьи, — наказывается лишением свободы на срок от трех до восьми лет."}]},{"n":"Статья 90","title":"Хулиганство","sub":[{"n":"1","text":"Хулиганство, то есть грубое нарушение общественного порядка, выражающее явное неуважение к обществу, совершенное:а) с применением насилия к гражданам либо угрозой его применения;б) по мотивам политической, идеологической, расовой, национальной или религиозной ненависти или вражды;в) на транспорте общего пользования, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до двух лет."},{"n":"2","text":"То же деяние, совершенное:а) группой лиц, группой лиц по предварительному сговору или организованной группой;б) с применением оружия или предметов, используемых в качестве оружия;в) с применением взрывчатых веществ или взрывных устройств, — наказывается лишением свободы на срок до пяти лет."}]},{"n":"Статья 91","title":"Вандализм","text":"Вандализм, то есть осквернение зданий или иных сооружений, порча имущества на общественном транспорте или в иных общественных местах, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"Статья 92","title":"Незаконное приобретение, передача, сбыт, хранение, перевозка или ношение оружия, его основных частей, боеприпасов","sub":[{"n":"1","text":"Незаконное приобретение, передача, сбыт, хранение, перевозка или ношение огнестрельного оружия, его основных частей и боеприпасов (за исключением гражданского огнестрельного гладкоствольного длинноствольного оружия, его основных частей и патронов к нему) — наказываются лишением свободы на срок до четырех лет со штрафом."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору, — наказываются лишением свободы на срок от двух до шести лет со штрафом."},{"n":"3","text":"Деяния, предусмотренные частями первой или второй настоящей статьи, совершенные организованной группой, — наказываются лишением свободы на срок от пяти до восьми лет со штрафом."}]},{"n":"Статья 93","title":"Незаконное изготовление оружия","text":"Незаконное изготовление или ремонт огнестрельного оружия, его основных частей, а равно незаконное изготовление боеприпасов — наказываются лишением свободы на срок до четырех лет со штрафом."},{"n":"Статья 94","title":"Хищение либо вымогательство оружия, боеприпасов, взрывчатых веществ и взрывных устройств","sub":[{"n":"1","text":"Хищение либо вымогательство огнестрельного оружия, комплектующих деталей к нему, боеприпасов, взрывчатых веществ или взрывных устройств — наказываются лишением свободы на срок от трех до семи лет."},{"n":"2","text":"То же деяние, совершенное группой лиц по предварительному сговору, лицом с использованием своего служебного положения, с применением насилия, не опасного для жизни или здоровья, — наказывается лишением свободы на срок от пяти до двенадцати лет со штрафом."}]},{"n":"Статья 95","title":"Незаконное приобретение, хранение, перевозка, изготовление, переработка наркотических средств","sub":[{"n":"1","text":"Незаконное приобретение, хранение, перевозка, изготовление, переработка без цели сбыта наркотических средств, психотропных веществ или их аналогов в значительном размере — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет."},{"n":"2","text":"Те же деяния, совершенные в крупном размере, — наказываются лишением свободы на срок от трех до десяти лет со штрафом."},{"n":"3","text":"Те же деяния, совершенные в особо крупном размере, — наказываются лишением свободы на срок от десяти до пятнадцати лет со штрафом."}]},{"n":"Статья 96","title":"Незаконные производство, сбыт или пересылка наркотических средств","sub":[{"n":"1","text":"Незаконные производство, сбыт или пересылка наркотических средств, психотропных веществ или их аналогов — наказываются лишением свободы на срок от четырех до восьми лет."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору, лицом с использованием своего служебного положения, в крупном размере, — наказываются лишением свободы на срок от восьми до двенадцати лет со штрафом."},{"n":"3","text":"Те же деяния, совершенные организованной группой либо в особо крупном размере, — наказываются лишением свободы на срок от двенадцати до двадцати лет со штрафом или пожизненным лишением свободы."}]},{"n":"Статья 97","title":"Организация либо содержание притонов для потребления наркотических средств","text":"Организация либо содержание притонов для потребления наркотических средств или психотропных веществ — наказываются лишением свободы на срок до четырех лет."},{"n":"Статья 98","title":"Незаконный оборот сильнодействующих или ядовитых веществ","text":"Незаконное изготовление, переработка, приобретение, хранение, перевозка или сбыт сильнодействующих или ядовитых веществ — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет."},{"n":"Статья 99","title":"Нарушение правил пожарной безопасности","sub":[{"n":"1","text":"Нарушение требований пожарной безопасности, совершенное лицом, на которое возложена обязанность по их соблюдению, если это повлекло по неосторожности причинение тяжкого вреда здоровью человека, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."},{"n":"2","text":"То же деяние, повлекшее по неосторожности смерть человека, — наказывается лишением свободы на срок до пяти лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."}]},{"n":"Статья 100","title":"Незаконная частная охранная и детективная деятельность","text":"Осуществление частной охранной или детективной деятельности без лицензии, если это деяние причинило крупный ущерб гражданам, организациям или государству либо сопряжено с извлечением дохода в крупном размере, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет."},{"n":"Статья 101","title":"Нарушение правил безопасности на объектах повышенной опасности","sub":[{"n":"1","text":"Нарушение правил безопасности при ведении горных, строительных или иных работ, если это повлекло по неосторожности причинение тяжкого вреда здоровью человека, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."},{"n":"2","text":"То же деяние, повлекшее по неосторожности смерть человека, — наказывается лишением свободы на срок до пяти лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."}]},{"h":"Глава 14. Преступления против здоровья населения и общественной нравственности"},{"n":"Статья 102","title":"Незаконный оборот алкогольной продукции","sub":[{"n":"1","text":"Производство, хранение, перевозка в целях сбыта или сбыт алкогольной продукции без соответствующей лицензии, без маркировки, либо с нарушением установленных требований — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору или организованной группой, — наказываются лишением свободы на срок до шести лет со штрафом."}]},{"n":"Статья 103","title":"Организация занятия проституцией","text":"Организация занятия проституцией другими лицами, а равно содержание притонов для занятия проституцией или систематическое предоставление помещений для занятия проституцией — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до пяти лет."},{"n":"Статья 104","title":"Надругательство над телами умерших и местами захоронения","sub":[{"n":"1","text":"Надругательство над телами умерших либо уничтожение, повреждение или осквернение мест захоронения, надмогильных сооружений или кладбищенских зданий, предназначенных для церемоний в связи с погребением умерших или их поминовением, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"2","text":"Те же деяния, совершенные группой лиц, группой лиц по предварительному сговору или организованной группой, по мотивам национальной, расовой, религиозной ненависти, — наказываются лишением свободы на срок до пяти лет."}]},{"n":"Статья 105","title":"Жестокое обращение с животными","sub":[{"n":"1","text":"Жестокое обращение с животными в целях причинения им боли или страданий, а равно из хулиганских побуждений или из корыстных побуждений, повлекшее их гибель или увечье, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"2","text":"То же деяние, совершенное группой лиц, группой лиц по предварительному сговору или организованной группой, с применением садистских методов, в присутствии малолетнего, — наказывается лишением свободы на срок до трех лет."}]},{"h":"Глава 15. Преступления против безопасности движения и эксплуатации транспорта"},{"n":"Статья 106","title":"Нарушение правил дорожного движения и эксплуатации транспортных средств","sub":[{"n":"1","text":"Нарушение лицом, управляющим автомобилем, трамваем либо другим механическим транспортным средством, правил дорожного движения или эксплуатации транспортных средств, повлекшее по неосторожности причинение тяжкого вреда здоровью человека, — наказывается ограничением свободы на срок до трех лет, либо принудительными работами на срок до двух лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет, либо арестом, либо лишением свободы на срок до двух лет с лишением права управлять транспортным средством на срок до трех лет."},{"n":"2","text":"То же деяние, повлекшее по неосторожности смерть человека, — наказывается принудительными работами на срок до четырех лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет либо лишением свободы на срок до пяти лет с лишением права управлять транспортным средством на срок до трех лет."},{"n":"3","text":"То же деяние, повлекшее по неосторожности смерть двух или более лиц, — наказывается принудительными работами на срок до пяти лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет либо лишением свободы на срок до семи лет с лишением права управлять транспортным средством на срок до трех лет."}]},{"n":"Статья 107","title":"Управление транспортным средством в состоянии опьянения","text":"Управление автомобилем, трамваем либо другим механическим транспортным средством лицом, находящимся в состоянии опьянения, подвергнутым административному наказанию за управление транспортным средством в состоянии опьянения, — наказывается штрафом, либо обязательными работами, либо принудительными работами, либо лишением свободы на срок до двух лет с лишением права управлять транспортным средством на срок до трех лет."},{"n":"Статья 108","title":"Оставление места дорожно-транспортного происшествия","text":"Оставление водителем в нарушение правил дорожного движения места дорожно-транспортного происшествия, участником которого он являлся, — наказывается штрафом, либо обязательными работами, либо административным арестом."},{"n":"Статья 109","title":"Недоброкачественный ремонт транспортных средств и выпуск их в эксплуатацию с техническими неисправностями","text":"Недоброкачественный ремонт транспортных средств, путей сообщения, средств сигнализации или связи либо иного транспортного оборудования, а равно выпуск в эксплуатацию технически неисправных транспортных средств лицом, ответственным за техническое состояние транспортных средств, если эти деяния повлекли по неосторожности причинение тяжкого вреда здоровью человека, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до двух лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."},{"n":"Статья 110","title":"Приведение в негодность транспортных средств или путей сообщения","text":"Разрушение, повреждение или иным способом приведение в негодное для эксплуатации состояние транспортного средства, путей сообщения, средств сигнализации или связи, если эти деяния повлекли по неосторожности причинение тяжкого вреда здоровью человека либо причинение крупного ущерба, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до четырех лет."},{"n":"Статья 111","title":"Нарушение правил перевозки опасных грузов","text":"Нарушение правил перевозки опасных грузов, если это деяние повлекло по неосторожности причинение тяжкого вреда здоровью человека, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до двух лет."},{"h":"Глава 16. Преступления в сфере компьютерной информации"},{"n":"Статья 112","title":"Неправомерный доступ к компьютерной информации","sub":[{"n":"1","text":"Неправомерный доступ к охраняемой законом компьютерной информации, если это деяние повлекло уничтожение, блокирование, модификацию либо копирование компьютерной информации, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо ограничением свободы на срок до двух лет, либо лишением свободы на тот же срок."},{"n":"2","text":"То же деяние, совершенное группой лиц по предварительному сговору или организованной группой, лицом с использованием своего служебного положения, с причинением крупного ущерба или из корыстной заинтересованности, — наказывается штрафом, либо лишением свободы на срок до пяти лет со штрафом."}]},{"n":"Статья 113","title":"Создание, использование и распространение вредоносных компьютерных программ","sub":[{"n":"1","text":"Создание, распространение или использование компьютерных программ либо иной компьютерной информации, заведомо предназначенных для несанкционированного уничтожения, блокирования, модификации, копирования компьютерной информации или нейтрализации средств защиты информации, — наказываются штрафом, либо ограничением свободы на срок до четырех лет, либо лишением свободы на тот же срок со штрафом."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору или организованной группой либо лицом с использованием своего служебного положения, — наказываются лишением свободы на срок до семи лет со штрафом."}]},{"n":"Статья 114","title":"Неправомерное воздействие на критическую информационную инфраструктуру","sub":[{"n":"1","text":"Создание, распространение и использование программ, заведомо предназначенных для неправомерного воздействия на критическую информационную инфраструктуру, — наказываются лишением свободы на срок до пяти лет со штрафом."},{"n":"2","text":"Неправомерный доступ к охраняемой компьютерной информации, содержащейся в критической информационной инфраструктуре, — наказывается лишением свободы на срок до шести лет со штрафом."}]},{"n":"Статья 115","title":"Мошенничество с использованием электронных средств платежа","sub":[{"n":"1","text":"Мошенничество с использованием электронных средств платежа, а равно хищение денежных средств с банковского счета, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет со штрафом."},{"n":"2","text":"То же деяние, совершенное группой лиц по предварительному сговору, лицом с использованием своего служебного положения, в крупном размере, — наказывается лишением свободы на срок до шести лет со штрафом."},{"n":"3","text":"Деяния, предусмотренные частями первой или второй настоящей статьи, совершенные организованной группой либо в особо крупном размере, — наказываются лишением свободы на срок до десяти лет со штрафом."}]},{"h":"Раздел IX. Преступления против государственной власти"},{"h":"Глава 17. Преступления против основ конституционного строя и безопасности государства"},{"n":"Статья 116","title":"Государственная измена","sub":[{"n":"1","text":"Государственная измена, то есть выдача гражданином Российской Федерации государственной тайны иностранному государству, международной либо иностранной организации, — наказывается лишением свободы на срок от двенадцати до двадцати лет со штрафом."},{"n":"2","text":"То же деяние, повлекшее тяжкие последствия, — наказывается лишением свободы на срок от пятнадцати до двадцати лет или пожизненным лишением свободы."}]},{"n":"Статья 117","title":"Шпионаж","sub":[{"n":"1","text":"Передача, собирание, похищение или хранение в целях передачи иностранному государству сведений, составляющих государственную тайну, — наказываются лишением свободы на срок от десяти до двадцати лет."},{"n":"2","text":"То же деяние, совершенное с использованием своего служебного положения или повлекшее тяжкие последствия, — наказывается лишением свободы на срок от пятнадцати до двадцати лет или пожизненным лишением свободы."}]},{"n":"Статья 118","title":"Посягательство на жизнь государственного или общественного деятеля","text":"Посягательство на жизнь государственного или общественного деятеля, совершенное в целях прекращения его государственной или иной политической деятельности либо из мести за такую деятельность, — наказывается лишением свободы на срок от двенадцати до двадцати лет либо пожизненным лишением свободы."},{"n":"Статья 119","title":"Насильственный захват власти или насильственное удержание власти","text":"Действия, направленные на насильственный захват власти или насильственное удержание власти в нарушение конституционного строя, а равно направленные на насильственное изменение конституционного строя, — наказываются лишением свободы на срок от двенадцати до двадцати лет."},{"n":"Статья 120","title":"Вооруженный мятеж","text":"Организация вооруженного мятежа либо активное участие в нем в целях свержения или насильственного изменения конституционного строя либо нарушения территориальной целостности государства — наказывается лишением свободы на срок от двенадцати до двадцати лет."},{"n":"Статья 121","title":"Публичные призывы к осуществлению экстремистской деятельности","sub":[{"n":"1","text":"Публичные призывы к осуществлению экстремистской деятельности — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до четырех лет."},{"n":"2","text":"Те же деяния, совершенные с использованием средств массовой информации либо информационно-телекоммуникационных сетей, — наказываются лишением свободы на срок до пяти лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."}]},{"n":"Статья 122","title":"Возбуждение ненависти либо вражды, а равно унижение человеческого достоинства","sub":[{"n":"1","text":"Действия, направленные на возбуждение ненависти либо вражды, а также на унижение достоинства человека либо группы лиц по признакам пола, расы, национальности, языка, происхождения, отношения к религии, принадлежности к какой-либо социальной группе, совершенные публично, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до четырех лет."},{"n":"2","text":"Те же деяния, совершенные с применением насилия или с угрозой его применения, лицом с использованием своего служебного положения, организованной группой, — наказываются лишением свободы на срок до шести лет со штрафом."}]},{"n":"Статья 123","title":"Организация экстремистского сообщества","sub":[{"n":"1","text":"Создание экстремистского сообщества, а равно руководство таким сообществом — наказываются лишением свободы на срок от восьми до двенадцати лет со штрафом."},{"n":"2","text":"Участие в экстремистском сообществе — наказывается лишением свободы на срок от четырех до восьми лет со штрафом."}]},{"n":"Статья 124","title":"Разглашение государственной тайны","sub":[{"n":"1","text":"Разглашение сведений, составляющих государственную тайну, лицом, которому она была доверена или стала известна по службе, — наказывается арестом, либо лишением свободы на срок до четырех лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."},{"n":"2","text":"То же деяние, повлекшее тяжкие последствия, — наказывается лишением свободы на срок от пяти до семи лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."}]},{"n":"Статья 125","title":"Посягательство на жизнь сотрудника правоохранительного органа","text":"Посягательство на жизнь сотрудника правоохранительного органа, военнослужащего, а равно их близких в целях воспрепятствования законной деятельности указанных лиц по охране общественного порядка и обеспечению общественной безопасности либо из мести за такую деятельность — наказывается лишением свободы на срок от двенадцати до двадцати лет либо пожизненным лишением свободы."},{"n":"Статья 126","title":"Оскорбление представителя власти","text":"Публичное оскорбление представителя власти при исполнении им своих должностных обязанностей или в связи с их исполнением — наказывается штрафом, либо обязательными работами, либо исправительными работами."},{"n":"Статья 127","title":"Применение насилия в отношении представителя власти","sub":[{"n":"1","text":"Применение насилия, не опасного для жизни или здоровья, либо угроза применения насилия в отношении представителя власти или его близких в связи с исполнением им своих должностных обязанностей — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до пяти лет."},{"n":"2","text":"Применение насилия, опасного для жизни или здоровья, в отношении указанных лиц — наказывается лишением свободы на срок до десяти лет."}]},{"n":"Статья 128","title":"Самоуправство","sub":[{"n":"1","text":"Самоуправство, то есть самовольное, вопреки установленному законом или иным нормативным правовым актом порядку совершение каких-либо действий, правомерность которых оспаривается организацией или гражданином, если такими действиями причинен существенный вред, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"2","text":"То же деяние, совершенное с применением насилия или с угрозой его применения, — наказывается лишением свободы на срок до пяти лет."}]},{"h":"Глава 18. Преступления против государственной власти, интересов государственной службы"},{"n":"Статья 129","title":"Злоупотребление должностными полномочиями","sub":[{"n":"1","text":"Использование должностным лицом своих служебных полномочий вопреки интересам службы, если это деяние совершено из корыстной или иной личной заинтересованности и повлекло существенное нарушение прав и законных интересов граждан или организаций либо охраняемых законом интересов общества или государства, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до четырех лет со штрафом."},{"n":"2","text":"То же деяние, совершенное лицом, занимающим государственную должность, а равно повлекшее тяжкие последствия, — наказывается штрафом, либо лишением свободы на срок до десяти лет со штрафом."}]},{"n":"Статья 130","title":"Превышение должностных полномочий","sub":[{"n":"1","text":"Совершение должностным лицом действий, явно выходящих за пределы его полномочий и повлекших существенное нарушение прав и законных интересов граждан или организаций, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до четырех лет."},{"n":"2","text":"То же деяние, совершенное лицом, занимающим государственную должность, с применением насилия или с угрозой его применения, с применением оружия или специальных средств, с причинением тяжких последствий, — наказывается штрафом, либо лишением свободы на срок до десяти лет со штрафом."}]},{"n":"Статья 131","title":"Присвоение полномочий должностного лица","text":"Присвоение государственным служащим или служащим органа местного самоуправления, не являющимся должностным лицом, полномочий должностного лица и совершение им в связи с этим действий, которые повлекли существенное нарушение прав и законных интересов граждан или организаций, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до трех лет."},{"n":"Статья 132","title":"Получение взятки","sub":[{"n":"1","text":"Получение должностным лицом, иностранным должностным лицом либо должностным лицом публичной международной организации лично или через посредника взятки в виде денег, ценных бумаг, иного имущества либо в виде незаконных оказания ему услуг имущественного характера за совершение действий (бездействие) в пользу взяткодателя, если такие действия входят в служебные полномочия должностного лица, — наказывается штрафом в размере от десятикратной до двадцатикратной суммы взятки, либо лишением свободы на срок до трех лет со штрафом."},{"n":"2","text":"Получение должностным лицом взятки в значительном размере — наказывается штрафом в размере до тридцатикратной суммы взятки, либо лишением свободы на срок до шести лет со штрафом."},{"n":"3","text":"Получение должностным лицом взятки за незаконные действия (бездействие) — наказывается штрафом в размере до сорокакратной суммы взятки, либо лишением свободы на срок до восьми лет со штрафом."},{"n":"4","text":"Деяния, предусмотренные частями первой, второй или третьей настоящей статьи, совершенные группой лиц по предварительному сговору или организованной группой, с вымогательством взятки, в крупном размере, — наказываются лишением свободы на срок до двенадцати лет со штрафом в размере до шестидесятикратной суммы взятки."},{"n":"5","text":"Деяния, предусмотренные частями первой, второй, третьей или четвертой настоящей статьи, совершенные в особо крупном размере, — наказываются лишением свободы на срок до пятнадцати лет со штрафом в размере до семидесятикратной суммы взятки."}]},{"n":"Статья 133","title":"Дача взятки","sub":[{"n":"1","text":"Дача взятки должностному лицу лично или через посредника — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до пяти лет со штрафом."},{"n":"2","text":"Дача взятки должностному лицу в значительном размере — наказывается штрафом, либо лишением свободы на срок до восьми лет со штрафом."},{"n":"3","text":"Дача взятки должностному лицу за совершение заведомо незаконных действий (бездействие) — наказывается штрафом, либо лишением свободы на срок до десяти лет со штрафом."}]},{"n":"Статья 134","title":"Посредничество во взяточничестве","sub":[{"n":"1","text":"Посредничество во взяточничестве, то есть непосредственная передача взятки по поручению взяткодателя или взяткополучателя либо иное способствование взяткодателю и (или) взяткополучателю в достижении либо реализации соглашения между ними о получении и даче взятки в значительном размере, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до пяти лет со штрафом."},{"n":"2","text":"Посредничество во взяточничестве за совершение заведомо незаконных действий (бездействие) либо лицом с использованием своего служебного положения — наказывается штрафом, либо лишением свободы на срок до семи лет со штрафом."}]},{"n":"Статья 135","title":"Служебный подлог","sub":[{"n":"1","text":"Служебный подлог, то есть внесение должностным лицом, а также государственным служащим или служащим органа местного самоуправления, не являющимся должностным лицом, в официальные документы заведомо ложных сведений, а равно внесение в указанные документы исправлений, искажающих их действительное содержание, если эти деяния совершены из корыстной или иной личной заинтересованности, — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до двух лет."},{"n":"2","text":"Те же деяния, повлекшие существенное нарушение прав и законных интересов граждан или организаций, — наказываются штрафом, либо лишением свободы на срок до четырех лет со штрафом."}]},{"n":"Статья 136","title":"Халатность","sub":[{"n":"1","text":"Халатность, то есть неисполнение или ненадлежащее исполнение должностным лицом своих обязанностей вследствие недобросовестного или небрежного отношения к службе, если это деяние повлекло причинение крупного ущерба или существенное нарушение прав и законных интересов граждан или организаций, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до одного года."},{"n":"2","text":"То же деяние, повлекшее по неосторожности причинение тяжкого вреда здоровью человека или смерть человека, — наказывается лишением свободы на срок до пяти лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."}]},{"n":"Статья 137","title":"Нецелевое расходование бюджетных средств","text":"Расходование бюджетных средств должностным лицом получателя бюджетных средств на цели, не соответствующие условиям их получения, определенным в утвержденном бюджете, бюджетной росписи, уведомлении о бюджетных ассигнованиях, смете доходов и расходов либо в ином документе, являющемся основанием для получения бюджетных средств, совершенное в крупном размере, — наказывается штрафом, либо лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет, либо лишением свободы на срок до двух лет."},{"h":"Глава 19. Преступления против правосудия"},{"n":"Статья 138","title":"Посягательство на жизнь лица, осуществляющего правосудие или предварительное расследование","text":"Посягательство на жизнь судьи, присяжного заседателя или иного лица, участвующего в отправлении правосудия, прокурора, следователя, лица, производящего дознание, защитника, эксперта, специалиста, судебного пристава, в связи с рассмотрением дел или материалов в суде либо производством предварительного расследования — наказывается лишением свободы на срок от двенадцати до двадцати лет либо пожизненным лишением свободы."},{"n":"Статья 139","title":"Угроза или насильственные действия в связи с осуществлением правосудия или производством предварительного расследования","sub":[{"n":"1","text":"Угроза убийством, причинением вреда здоровью, уничтожением или повреждением имущества в отношении судьи, присяжного заседателя или иного лица, участвующего в отправлении правосудия, а равно их близких в связи с рассмотрением дел или материалов в суде — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до трех лет."},{"n":"2","text":"То же деяние, совершенное в отношении прокурора, следователя, лица, производящего дознание, защитника, эксперта, специалиста, судебного пристава, а равно их близких в связи с производством предварительного расследования либо исполнением приговора, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до четырех лет."}]},{"n":"Статья 140","title":"Привлечение заведомо невиновного к уголовной ответственности","text":"Привлечение заведомо невиновного к уголовной ответственности — наказывается лишением свободы на срок до пяти лет."},{"n":"Статья 141","title":"Незаконное освобождение от уголовной ответственности","text":"Незаконное освобождение от уголовной ответственности лица, подозреваемого или обвиняемого в совершении преступления, прокурором, следователем или лицом, производящим дознание, — наказывается лишением свободы на срок до семи лет со штрафом."},{"n":"Статья 142","title":"Незаконные задержание, заключение под стражу или содержание под стражей","sub":[{"n":"1","text":"Заведомо незаконное задержание — наказывается ограничением свободы на срок до трех лет либо лишением свободы на тот же срок."},{"n":"2","text":"Заведомо незаконные заключение под стражу или содержание под стражей — наказываются лишением свободы на срок до четырех лет."}]},{"n":"Статья 143","title":"Принуждение к даче показаний","sub":[{"n":"1","text":"Принуждение подозреваемого, обвиняемого, потерпевшего, свидетеля к даче показаний либо эксперта к даче заключения путем применения угроз, шантажа или иных незаконных действий со стороны следователя или лица, производящего дознание, — наказывается лишением свободы на срок до пяти лет."},{"n":"2","text":"То же деяние, соединенное с применением насилия, издевательств или пытки, — наказывается лишением свободы на срок от пяти до двенадцати лет."}]},{"n":"Статья 144","title":"Фальсификация доказательств","sub":[{"n":"1","text":"Фальсификация доказательств по гражданскому или административному делу лицом, участвующим в деле, или его представителем — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"2","text":"Фальсификация доказательств по уголовному делу лицом, производящим дознание, следователем, прокурором или защитником — наказывается лишением свободы на срок до семи лет со штрафом."}]},{"n":"Статья 145","title":"Вынесение заведомо неправосудного приговора, решения или иного судебного акта","sub":[{"n":"1","text":"Вынесение судьей заведомо неправосудного приговора, решения или иного судебного акта — наказывается штрафом, либо лишением свободы на срок до четырех лет со штрафом."},{"n":"2","text":"То же деяние, связанное с вынесением незаконного приговора суда к лишению свободы или повлекшее иные тяжкие последствия, — наказывается лишением свободы на срок от пяти до десяти лет со штрафом."}]},{"n":"Статья 146","title":"Заведомо ложный донос","sub":[{"n":"1","text":"Заведомо ложный донос о совершении преступления — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до двух лет."},{"n":"2","text":"То же деяние, соединенное с обвинением лица в совершении тяжкого или особо тяжкого преступления, — наказывается штрафом, либо лишением свободы на срок до шести лет со штрафом."}]},{"n":"Статья 147","title":"Заведомо ложные показания, заключение эксперта или неправильный перевод","sub":[{"n":"1","text":"Заведомо ложные показания свидетеля, потерпевшего либо заключение или показание эксперта, а равно заведомо неправильный перевод в суде либо при производстве предварительного расследования — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до пяти лет."},{"n":"2","text":"Те же деяния, соединенные с обвинением лица в совершении тяжкого или особо тяжкого преступления, — наказываются лишением свободы на срок от пяти до десяти лет."}]},{"n":"Статья 148","title":"Отказ свидетеля или потерпевшего от дачи показаний","text":"Отказ свидетеля или потерпевшего от дачи показаний, за исключением случаев, когда отказ от дачи показаний вызван уважительными причинами, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"Статья 149","title":"Подкуп или принуждение к даче показаний","sub":[{"n":"1","text":"Подкуп свидетеля, потерпевшего в целях дачи ими ложных показаний либо эксперта в целях дачи ими ложного заключения — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет."},{"n":"2","text":"Принуждение свидетеля, потерпевшего к даче ложных показаний, соединенное с шантажом, угрозой убийством, причинением вреда здоровью, уничтожением или повреждением имущества, — наказывается лишением свободы на срок до пяти лет."}]},{"n":"Статья 150","title":"Укрывательство преступлений","text":"Заранее не обещанное укрывательство особо тяжких преступлений — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до двух лет."},{"n":"Статья 151","title":"Побег из места лишения свободы, из-под ареста или из-под стражи","sub":[{"n":"1","text":"Побег из места лишения свободы, из-под ареста или из-под стражи, совершенный лицом, отбывающим наказание или находящимся в предварительном заключении, — наказывается лишением свободы на срок до четырех лет."},{"n":"2","text":"То же деяние, совершенное группой лиц по предварительному сговору или организованной группой, с применением насилия, опасного для жизни или здоровья, либо с угрозой применения такого насилия, — наказывается лишением свободы на срок до восьми лет."}]},{"n":"Статья 152","title":"Уклонение от отбывания ограничения свободы, лишения свободы","text":"Уклонение от отбывания ограничения свободы, лишения свободы, а равно от применения иных мер уголовно-правового характера — наказывается лишением свободы на срок до двух лет."},{"n":"Статья 153","title":"Разглашение данных предварительного расследования","text":"Разглашение данных предварительного расследования лицом, предупрежденным в установленном законом порядке о недопустимости их разглашения, если оно совершено без согласия следователя или лица, производящего дознание, — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом."},{"n":"Статья 154","title":"Неисполнение приговора суда, решения суда или иного судебного акта","text":"Злостное неисполнение представителем власти, государственным служащим, служащим органа местного самоуправления, а также служащим государственного или муниципального учреждения вступивших в законную силу приговора суда, решения суда или иного судебного акта — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо арестом, либо лишением свободы на срок до двух лет."},{"n":"Статья 155","title":"Организация незаконной миграции","text":"Организация незаконного въезда в Российскую Федерацию иностранных граждан или лиц без гражданства, их незаконного пребывания в Российской Федерации или незаконного транзитного проезда через территорию Российской Федерации — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до пяти лет со штрафом."},{"n":"Статья 156","title":"Фиктивная регистрация гражданина","text":"Фиктивная регистрация гражданина Российской Федерации по месту пребывания или по месту жительства в жилом помещении без намерения проживать в нем — наказывается штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет."},{"n":"Статья 157","title":"Подделка или уничтожение идентификационного номера транспортного средства","sub":[{"n":"1","text":"Подделка или уничтожение идентификационного номера, номера кузова, шасси, двигателя, а также подделка государственного регистрационного знака транспортного средства в целях эксплуатации или сбыта транспортного средства, а равно сбыт транспортного средства с заведомо поддельным идентификационным номером — наказываются штрафом, либо обязательными работами, либо исправительными работами, либо лишением свободы на срок до трех лет."},{"n":"2","text":"Те же деяния, совершенные группой лиц по предварительному сговору или организованной группой, — наказываются лишением свободы на срок до шести лет со штрафом."}]},{"h":"Раздел X. Преступления против военной службы"},{"h":"Глава 20. Преступления против порядка подчиненности и уставных взаимоотношений"},{"n":"Статья 158","title":"Неисполнение приказа","sub":[{"n":"1","text":"Неисполнение подчиненным приказа начальника, отданного в установленном порядке, причинившее существенный вред интересам службы, — наказывается ограничением по военной службе, либо арестом, либо содержанием в дисциплинарной воинской части."},{"n":"2","text":"То же деяние, совершенное группой лиц, группой лиц по предварительному сговору или организованной группой, а равно повлекшее тяжкие последствия, — наказывается лишением свободы на срок до пяти лет."}]},{"n":"Статья 159","title":"Сопротивление начальнику или принуждение его к нарушению обязанностей военной службы","sub":[{"n":"1","text":"Сопротивление начальнику, а равно иному лицу, исполняющему обязанности военной службы, или принуждение его к нарушению этих обязанностей, сопряженные с насилием или с угрозой его применения, — наказываются ограничением по военной службе, либо содержанием в дисциплинарной воинской части, либо лишением свободы на срок до пяти лет."},{"n":"2","text":"Те же деяния, совершенные группой лиц, с применением оружия, с причинением тяжкого вреда здоровью либо иных тяжких последствий, — наказываются лишением свободы на срок до восьми лет."}]},{"n":"Статья 160","title":"Насильственные действия в отношении начальника","sub":[{"n":"1","text":"Нанесение побоев или применение иного насилия в отношении начальника, совершенные во время исполнения им обязанностей военной службы, — наказываются ограничением по военной службе, либо содержанием в дисциплинарной воинской части, либо лишением свободы на срок до пяти лет."},{"n":"2","text":"Те же деяния, совершенные с применением оружия, с причинением тяжкого вреда здоровью либо иных тяжких последствий, — наказываются лишением свободы на срок до восьми лет."}]},{"n":"Статья 161","title":"Нарушение уставных правил взаимоотношений между военнослужащими","sub":[{"n":"1","text":"Нарушение уставных правил взаимоотношений между военнослужащими при отсутствии между ними отношений подчиненности, связанное с унижением чести и достоинства или издевательством над потерпевшим либо сопряженное с насилием, — наказывается содержанием в дисциплинарной воинской части, либо лишением свободы на срок до трех лет."},{"n":"2","text":"То же деяние, совершенное в отношении двух или более лиц, группой лиц, с применением оружия, с причинением тяжкого вреда здоровью либо иных тяжких последствий, — наказывается лишением свободы на срок до восьми лет."}]},{"h":"Глава 21. Преступления против порядка прохождения военной службы"},{"n":"Статья 162","title":"Самовольное оставление части или места службы","sub":[{"n":"1","text":"Самовольное оставление части или места службы, а равно неявка в срок без уважительных причин на службу продолжительностью свыше двух суток, но не более десяти суток, — наказывается арестом или содержанием в дисциплинарной воинской части."},{"n":"2","text":"Те же деяния продолжительностью свыше десяти суток, но не более месяца, — наказываются содержанием в дисциплинарной воинской части на срок до двух лет или лишением свободы на срок до двух лет."},{"n":"3","text":"Те же деяния продолжительностью свыше месяца, — наказываются лишением свободы на срок до пяти лет."}]},{"n":"Статья 163","title":"Дезертирство","sub":[{"n":"1","text":"Дезертирство, то есть самовольное оставление части или места службы в целях уклонения от прохождения военной службы, а равно неявка в тех же целях на службу — наказывается лишением свободы на срок до семи лет."},{"n":"2","text":"Дезертирство с оружием, вверенным по службе, а равно дезертирство, совершенное группой лиц по предварительному сговору или организованной группой, — наказывается лишением свободы на срок от трех до десяти лет."}]},{"n":"Статья 164","title":"Нарушение правил несения боевого дежурства","sub":[{"n":"1","text":"Нарушение правил несения боевого дежурства, если это деяние повлекло или могло повлечь причинение вреда интересам безопасности государства, — наказывается ограничением по военной службе, либо арестом, либо содержанием в дисциплинарной воинской части, либо лишением свободы на срок до трех лет."},{"n":"2","text":"То же деяние, повлекшее тяжкие последствия, — наказывается лишением свободы на срок до семи лет."}]},{"n":"Статья 165","title":"Нарушение уставных правил караульной службы","sub":[{"n":"1","text":"Нарушение уставных правил караульной службы лицом, входящим в состав караула, если это деяние повлекло причинение вреда охраняемым караулом объектам, — наказывается ограничением по военной службе, либо арестом, либо содержанием в дисциплинарной воинской части, либо лишением свободы на срок до трех лет."},{"n":"2","text":"То же деяние, повлекшее тяжкие последствия, — наказывается лишением свободы на срок до семи лет."}]},{"n":"Статья 166","title":"Утрата военного имущества","text":"Нарушение правил сбережения вверенного для служебного пользования военного имущества, если это повлекло по неосторожности утрату или повреждение указанного имущества, — наказывается штрафом, либо ограничением по военной службе, либо арестом, либо содержанием в дисциплинарной воинской части, либо лишением свободы на срок до двух лет."},{"n":"Статья 167","title":"Нарушение правил обращения с оружием и предметами, представляющими повышенную опасность","sub":[{"n":"1","text":"Нарушение правил обращения с оружием, боеприпасами, радиоактивными материалами, взрывчатыми или иными веществами и предметами, представляющими повышенную опасность для окружающих, если это повлекло по неосторожности причинение тяжкого вреда здоровью человека, — наказывается ограничением по военной службе, либо содержанием в дисциплинарной воинской части, либо лишением свободы на срок до двух лет."},{"n":"2","text":"То же деяние, повлекшее по неосторожности смерть человека, — наказывается лишением свободы на срок до пяти лет."}]},{"h":"Раздел XI. Преступления против мира и безопасности человечества"},{"h":"Глава 22. Преступления против мира и безопасности человечества"},{"n":"Статья 168","title":"Планирование, подготовка, развязывание или ведение агрессивной войны","sub":[{"n":"1","text":"Планирование, подготовка или развязывание агрессивной войны — наказываются лишением свободы на срок от семи до пятнадцати лет."},{"n":"2","text":"Ведение агрессивной войны — наказывается лишением свободы на срок от десяти до двадцати лет."}]},{"n":"Статья 169","title":"Публичные призывы к развязыванию агрессивной войны","sub":[{"n":"1","text":"Публичные призывы к развязыванию агрессивной войны — наказываются штрафом в размере до трехсот тысяч рублей, либо лишением свободы на срок до трех лет."},{"n":"2","text":"Те же деяния, совершенные с использованием средств массовой информации либо лицом, занимающим государственную должность, — наказываются штрафом в размере от ста тысяч до пятисот тысяч рублей, либо лишением свободы на срок до пяти лет с лишением права занимать определенные должности или заниматься определенной деятельностью на срок до трех лет."}]},{"n":"Статья 170","title":"Разработка, производство, накопление, приобретение или сбыт оружия массового поражения","text":"Разработка, производство, накопление, приобретение или сбыт химического, биологического, токсинного, а также другого вида оружия массового поражения, запрещенного международным договором Российской Федерации, — наказываются лишением свободы на срок от пяти до десяти лет."},{"n":"Статья 171","title":"Применение запрещенных средств и методов ведения войны","sub":[{"n":"1","text":"Жестокое обращение с военнопленными или гражданским населением, депортация гражданского населения, разграбление национального имущества на оккупированной территории, применение в вооруженном конфликте средств и методов, запрещенных международным договором Российской Федерации, — наказываются лишением свободы на срок до двадцати лет."},{"n":"2","text":"Применение оружия массового поражения, запрещенного международным договором Российской Федерации, — наказывается лишением свободы на срок от десяти до двадцати лет."}]},{"n":"Статья 172","title":"Геноцид","text":"Действия, направленные на полное или частичное уничтожение национальной, этнической, расовой или религиозной группы как таковой путем убийства членов этой группы, причинения тяжкого вреда их здоровью, насильственного воспрепятствования деторождению, принудительной передачи детей, насильственного переселения либо иного создания жизненных условий, рассчитанных на физическое уничтожение членов этой группы, — наказываются лишением свободы на срок от двенадцати до двадцати лет либо пожизненным лишением свободы."},{"n":"Статья 173","title":"Экоцид","text":"Массовое уничтожение растительного или животного мира, отравление атмосферы или водных ресурсов, а также совершение иных действий, способных вызвать экологическую катастрофу, — наказывается лишением свободы на срок от двенадцати до двадцати лет."},{"n":"Статья 174","title":"Наемничество","sub":[{"n":"1","text":"Вербовка, обучение, финансирование или иное материальное обеспечение наемника, а равно его использование в вооруженном конфликте или военных действиях — наказываются лишением свободы на срок от восьми до пятнадцати лет со штрафом."},{"n":"2","text":"Те же деяния, совершенные лицом с использованием своего служебного положения или в отношении несовершеннолетнего, — наказываются лишением свободы на срок от десяти до восемнадцати лет со штрафом."},{"n":"3","text":"Участие наемника в вооруженном конфликте или военных действиях — наказывается лишением свободы на срок от восьми до пятнадцати лет со штрафом."}]},{"n":"Статья 175","title":"Нападение на лиц или учреждения, которые пользуются международной защитой","text":"Нападение на представителя иностранного государства или сотрудника международной организации, пользующегося международной защитой, а равно на служебные или жилые помещения либо транспортные средства таких лиц — наказывается лишением свободы на срок от пяти до десяти лет."},{"n":"Статья 176","title":"Акты международного терроризма","text":"Совершение вне пределов Российской Федерации взрыва, поджога или иных действий, создающих опасность гибели человека, причинения значительного имущественного ущерба либо наступления иных тяжких последствий, в целях нарушения мирного сосуществования государств и народов — наказывается лишением свободы на срок от десяти до двадцати лет либо пожизненным лишением свободы."}]};
